<script setup>
import { ref, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, command, requestId } from '../../api/client'
import { workspace, money, labels, can } from '../../services/workspace'
const route = useRoute(), router = useRouter(), orders = ref([]), detail = ref(null), pagers = ref([]), busy = ref(false), error = ref(''), message = ref('')
const amount = ref(''), method = ref('cash'), reference = ref(''), note = ref(''), receiver = ref('Khách tại quầy'), pager = ref(''), refundPayment = ref(''), refundAmount = ref(''), reason = ref('')
const keys = new Map()
async function refresh() { orders.value = await api('/api/v1/operations/orders?branch=' + workspace.branch); if (route.query.id) { detail.value = await api('/api/v1/operations/orders/' + encodeURIComponent(route.query.id)); amount.value = String(Number(detail.value.invoice.total) - Number(detail.value.invoice.paid_total)); pagers.value = await api('/api/v1/operations/references/pagers?branch=' + workspace.branch) } }
onMounted(async () => { try { await refresh() } catch (e) { error.value = e.message } })
async function run(path, data = {}) { busy.value = true; error.value = ''; message.value = ''; const fingerprint = path + JSON.stringify(data); if (!keys.has(fingerprint)) keys.set(fingerprint, requestId()); try { await command(path, { ...data, requestId: keys.get(fingerprint) }); keys.delete(fingerprint); message.value = 'Server đã ghi nhận thao tác.'; await refresh() } catch (e) { error.value = e.message } finally { busy.value = false } }
function select(order) { router.push('/app/orders?id=' + order.id) }
function print() { window.print() }
</script>
<template><h1>Đơn hàng đang chạy</h1><p>Giữ nguyên nội dung khi gửi lại sau lỗi mạng. Mọi chuyển trạng thái đều do server kiểm tra.</p><p v-if="error" role="alert" class="error">{{ error }}</p><p v-if="message" role="status" class="success">{{ message }}</p><fieldset :disabled="busy"><div class="actions"><button class="secondary" @click="refresh().catch(e => error = e.message)">Tải lại dữ liệu</button><RouterLink class="button" to="/app/pos">Tạo đơn</RouterLink></div>
<div class="table-scroll"><table><thead><tr><th>Đơn</th><th>Kênh/bàn</th><th>Trạng thái</th><th>Phải thu</th><th>Đã thu</th><th></th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{ o.invoice_no }}</td><td>{{ o.channel }} {{ o.table_code }}</td><td>{{ labels[o.status] || o.status }}</td><td>{{ money(o.total) }}</td><td>{{ money(o.paid_total) }}</td><td><button class="secondary" @click="select(o)">Mở</button></td></tr></tbody></table></div>
<template v-if="detail"><section class="card"><h2>{{ detail.invoice.invoice_no }}</h2><p>{{ labels[detail.invoice.status] }} · Phải thu {{ money(detail.invoice.total) }} · Đã thu {{ money(detail.invoice.paid_total) }} · Đã hoàn {{ money(detail.refunded) }}</p><p v-if="detail.quoteWarning" class="error">{{ detail.quoteWarning }}</p><p v-if="detail.invoice.status === 'draft'">Giá hiện tại để xác nhận: <strong>{{ money(detail.quotedTotal) }}</strong>. Xác nhận sẽ giữ nguyên liệu, chuyển món đến quầy và tạo ticket.</p><div class="actions" v-if="detail.invoice.status === 'draft' && can('order.confirm')"><button :disabled="!!detail.quoteWarning" @click="run('/orders/' + detail.invoice.id + '/confirm', { expectedTotal: detail.quotedTotal })">Xác nhận giá và chuyển quầy</button><button class="danger" :disabled="!reason.trim()" @click="run('/orders/' + detail.invoice.id + '/reject', { reason })">Từ chối đơn</button></div><label>Lý do xử lý / từ chối<input v-model="reason" maxlength="300"></label><button class="secondary" @click="print">In thông tin đơn hiện tại</button></section>
<section class="card"><h2>Chế biến và bàn giao từng món</h2><div v-for="l in detail.lines" :key="l.id" class="line"><h3>{{ l.item_name }} × {{ l.quantity }} · {{ money(l.unit_price) }}</h3><p>{{ labels[l.status] }} · {{ l.station_name }} · Đã giao {{ l.handed_qty }}/{{ l.quantity }}</p><p v-if="l.note" class="notice">Ghi chú cần đọc: {{ l.note }}</p><div class="actions" v-if="can('prep.work')"><button v-if="l.status === 'waiting' && !l.accepted_by" @click="run('/lines/' + l.id + '/accept')">Nhận làm</button><button v-if="l.status === 'waiting' && l.accepted_by && !l.started_at" @click="run('/lines/' + l.id + '/start')">Bắt đầu và tiêu hao kho</button><button v-if="l.status === 'in_progress' && l.started_at" @click="run('/lines/' + l.id + '/ready')">Hoàn tất chế biến</button></div><button v-if="can('order.confirm') && l.status === 'waiting'" class="danger" :disabled="!reason.trim()" @click="run('/lines/' + l.id + '/cancel', { reason })">Hủy món chưa làm</button></div></section>
<section class="card" v-if="can('ticket.work')"><h2>Ticket và thiết bị rung</h2><label>Người nhận món<input v-model="receiver" maxlength="100"></label><label>Thiết bị sẵn sàng<select v-model="pager"><option value="">Chọn thiết bị</option><option v-for="p in pagers.filter(p => ['ready','returned'].includes(p.status))" :key="p.id" :value="p.id">{{ p.code }}</option></select></label><div v-for="t in detail.tickets" :key="t.id" class="line"><h3>{{ t.ticket_no }} · {{ labels[t.status] }}</h3><p>Thiết bị: {{ t.pager_code || 'Không dùng' }} · {{ t.returned_at ? 'Đã thu hồi' : t.pager_status }}</p><div class="actions"><button v-if="!t.pager_id && t.status !== 'closed'" :disabled="!pager" @click="run('/tickets/' + t.id + '/pager', { pagerId: pager })">Cấp thiết bị</button><button v-if="t.status !== 'closed'" @click="run('/tickets/' + t.id + '/call', { reason: 'Nhân viên gọi hoặc bấm bộ rung thủ công' })">Ghi nhận gọi khách thủ công</button><button v-if="t.pager_id && !t.returned_at" @click="run('/tickets/' + t.id + '/return', { reason: 'Đã nhận lại thiết bị' })">Đã thu thiết bị</button><button v-if="t.status !== 'closed'" @click="run('/tickets/' + t.id + '/close', { reason: 'Đối chiếu đã giao đủ' })">Đóng ticket</button><button v-if="t.status === 'closed' && can('ticket.reopen')" :disabled="!reason.trim()" @click="run('/tickets/' + t.id + '/reopen', { reason })">Mở lại có lý do</button></div><div v-for="l in detail.lines.filter(l => l.status === 'ready')" :key="l.id" class="actions"><button :disabled="!receiver.trim()" @click="run('/tickets/' + t.id + '/handover', { lineId: l.id, quantity: 1, receiver, note: 'Đối chiếu ticket và giao một phần' })">Giao 1 {{ l.item_name }}</button><button :disabled="!receiver.trim()" @click="run('/tickets/' + t.id + '/handover', { lineId: l.id, quantity: l.quantity - l.handed_qty, receiver, note: 'Đối chiếu và giao phần còn lại' })">Giao đủ phần còn lại</button></div></div></section>
<section class="card" v-if="can('payment.collect')"><h2>Thu tiền thực tế đã xác nhận</h2><p class="notice">Đây là ghi nhận thủ công. Chuyển khoản/thẻ/ví chỉ xác nhận sau khi đã đối chiếu tiền thực nhận; không gửi lệnh thu đến ngân hàng.</p><form v-if="['confirmed','partially_paid'].includes(detail.invoice.status)" @submit.prevent="run('/orders/' + detail.invoice.id + '/payments', { amount: String(amount), method, txRef: reference, note })"><label>Số thu giữ lại (không gồm tiền trả lại)<input v-model="amount" type="number" min="1" step="1" required></label><label>Phương thức<select v-model="method"><option value="cash">Tiền mặt</option><option value="transfer">Chuyển khoản thủ công</option><option value="card">Thẻ đã đối chiếu</option><option value="wallet">Ví đã đối chiếu</option></select></label><label>Mã giao dịch duy nhất<input v-model="reference" maxlength="80" required></label><label>Thông tin đối chiếu<input v-model="note" maxlength="300" :required="method !== 'cash'"></label><button>Xác nhận khoản thu</button></form><table><thead><tr><th>Loại</th><th>Phương thức</th><th>Số tiền</th><th>Mã đối chiếu</th><th>Trạng thái</th></tr></thead><tbody><tr v-for="p in detail.payments" :key="p.id"><td>{{ labels[p.kind] }}</td><td>{{ p.method }}</td><td>{{ money(p.amount) }}</td><td>{{ p.tx_ref }}</td><td>{{ labels[p.status] }}</td></tr></tbody></table></section>
<section class="card" v-if="can('refund.request')"><h2>Đề nghị hoàn tiền</h2><form @submit.prevent="run('/orders/' + detail.invoice.id + '/refund-requests', { paymentId: refundPayment, amount: String(refundAmount), reason })"><label>Khoản thu gốc<select v-model="refundPayment" required><option value="">Chọn khoản thu</option><option v-for="p in detail.payments.filter(p => p.kind === 'collect' && p.status === 'succeeded')" :key="p.id" :value="p.id">{{ p.tx_ref }} · {{ money(p.amount) }}</option></select></label><label>Số tiền cần hoàn<input v-model="refundAmount" type="number" min="1" step="1" required></label><label>Lý do<input v-model="reason" required maxlength="300"></label><button>Gửi người khác duyệt</button></form><div v-for="a in detail.approvals" :key="a.id" class="line"><p>{{ a.requester_name }} đề nghị {{ money(a.amount) }} · {{ a.reason }} · {{ labels[a.status] }}</p><div class="actions" v-if="a.status === 'pending' && can('refund.approve')"><button :disabled="!reason.trim()" @click="run('/approvals/' + a.id + '/decision', { approve: true, reason })">Duyệt hoàn</button><button class="danger" :disabled="!reason.trim()" @click="run('/approvals/' + a.id + '/decision', { approve: false, reason })">Từ chối</button></div><form v-if="a.status === 'approved' && !detail.payments.some(p => p.approval_id === a.id && p.status === 'succeeded') && can('payment.collect')" @submit.prevent="run('/orders/' + detail.invoice.id + '/refunds', { approvalId: a.id, txRef: reference, note })"><label>Mã giao dịch hoàn (khác khoản thu)<input v-model="reference" maxlength="80" required></label><label>Đã hoàn thực tế cho ai, bằng cách nào<input v-model="note" maxlength="300" required></label><button>Xác nhận đã hoàn thực tế</button></form></div></section>
</template></fieldset></template>
